namespace Erlang;

internal sealed class DistributionDeferredExitReason : IDisposable
{
    private ReadOnlyMemory<byte> payload;
    private readonly Func<bool> forbiddenGateHeld;
    private readonly Func<ReadOnlyMemory<byte>, EtfDecodedTerm> decode;
    private readonly TaskCompletionSource<EtfDecodedTerm?> completed = new(TaskCreationOptions.RunContinuationsAsynchronously);
    private int claimed;

    internal DistributionDeferredExitReason(
        ReadOnlyMemory<byte> payload,
        Func<bool> forbiddenGateHeld,
        Func<ReadOnlyMemory<byte>, EtfDecodedTerm> decode
    )
    {
        // Own the raw bytes; do not parse even an empty/malformed dropped reason.
        this.payload = payload.ToArray();
        this.forbiddenGateHeld = forbiddenGateHeld;
        this.decode = decode;
    }

    internal Task<EtfDecodedTerm?> Prepare(
        Func<bool> shouldDecode,
        Action<Exception> malformedReason
    )
    {
        if (forbiddenGateHeld())
            throw new InvalidOperationException(DistributionDeferredExitReasonDiagnostics.Locked);
        if (Volatile.Read(ref claimed) != 0)
            return completed.Task;
        if (Interlocked.CompareExchange(ref claimed, 1, 0) != 0)
            return completed.Task;
        bool eligible;
        try
        {
            // Caller commits native target/link drop/removal before reason decode.
            // No private lock is held while running either supplied callback.
            eligible = shouldDecode();
        }
        catch (Exception exception)
        {
            Finish(null, exception);

            return completed.Task;
        }
        if (!eligible)
        {
            Finish(null, null);

            return completed.Task;
        }
        try
        {
            if (forbiddenGateHeld())
                throw new InvalidOperationException(DistributionDeferredExitReasonDiagnostics.Locked);
            EtfDecodedTerm result = decode(payload);
            Finish(result, null);
        }
        catch (Exception exception)
        {
            if (IsMalformed(exception))
            {
                try
                {
                    // Caller closes only its captured connection generation.
                    malformedReason(exception);
                }
                catch (Exception closeFailure)
                {
                    Finish(null, new AggregateException(exception, closeFailure));

                    return completed.Task;
                }
            }
            Finish(null, exception);
        }

        return completed.Task;
    }

    public void Dispose()
    {
        if (Interlocked.CompareExchange(ref claimed, 1, 0) != 0)
            return;
        Finish(null, null);
    }

    private void Finish(EtfDecodedTerm? result, Exception? exception)
    {
        payload = ReadOnlyMemory<byte>.Empty;
        if (exception is null)
            completed.TrySetResult(result);
        else
            completed.TrySetException(exception);
    }

    private static bool IsMalformed(Exception exception)
        => exception is ArgumentException or EndOfStreamException or InvalidDataException or FormatException or OverflowException ||
            exception is ErlangException { Reason: Atom { Name: ErlangErrorReasons.BadArgument or ErlangErrorReasons.SystemLimit } };
}

namespace Erlang;

internal static class DistributionDeferredExitReasonDiagnostics
{
    internal const string Locked = "Deferred exit reason factories must execute outside runtime and mailbox gates.";
    internal const string Payload = "Deferred distribution reason is not an allowed versioned ETF payload.";
}

namespace Erlang;

internal sealed class DistributionSignalDrain
{
    [ThreadStatic]
    private static DistributionSignalDrain? current;
    private readonly object gate = new();
    private TaskCompletionSource? completed;

    internal bool IsCurrent => ReferenceEquals(current, this);

    internal void Run(Action drain)
    {
        if (IsCurrent)
            return;
        while (true)
        {
            Task? preceding;
            lock (gate)
            {
                preceding = completed?.Task;
                if (preceding is null)
                    completed = new(TaskCreationOptions.RunContinuationsAsynchronously);
            }
            if (preceding is null)
                break;
            preceding.GetAwaiter().GetResult();
        }
        DistributionSignalDrain? parent = current;
        current = this;
        try
        {
            drain();
        }
        finally
        {
            current = parent;
            TaskCompletionSource finished;
            lock (gate)
            {
                finished = completed!;
                completed = null;
            }
            finished.TrySetResult();
        }
    }
}

using System.Diagnostics;

namespace Erlang;

public sealed partial class Mailbox
{
    private readonly object gate = new();
    private readonly LinkedList<Entry> messages = new();
    private LinkedListNode<Entry>? lastPriority;
    private int pending;
    private int admittedCount;
    private long precedenceRevision;
    private long mutationRevision;
    private long pulseRevision;
    private TaskCompletionSource changed = NewSignal();
    internal Func<bool>? HaltRequested { get; init; }
    internal Action? ProcessSignals { get; init; }
    internal Func<ValueTask<long>>? WaitForExecution { get; init; }
    internal Func<bool>? ExecutionBlocked { get; init; }
    internal Action? MessageReceived { get; init; }
    internal Action<Term, Term?>? MessageAdmitted { get; init; }
    internal Action<int>? QueueLengthChanged { get; init; }
    internal Action<Term, SequenceTraceToken?, bool>? TraceReceived { get; init; }
    internal Action? ReceiveTimedOut { get; init; }
    internal Action<bool>? WaitingStateChanged { get; init; }

    private readonly record struct Entry(
        Term Value,
        Func<bool?>? Admission,
        bool Control = false,
        SequenceTraceToken? TraceToken = null,
        bool PreserveTrace = false,
        Term? From = null,
        bool TraceAdmission = true,
        Term? DistributionTraceToken = null,
        Func<DeferredMailboxAdmission?>? DeferredPreparation = null,
        Action? DeferredRelease = null,
        bool Deferred = false
    );

    private static TaskCompletionSource NewSignal() => new(TaskCreationOptions.RunContinuationsAsynchronously);

    internal void StopForHalt()
    {
        lock (gate)
        {
            mutationRevision++;
            precedenceRevision++;
            foreach (var entry in messages)
                entry.DeferredRelease?.Invoke();
            messages.Clear();
            pending = 0;
            admittedCount = 0;
            lastPriority = null;
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
    }

    private void ThrowIfHalted()
    {
        if (HaltRequested?.Invoke() == true)
            throw new OperationCanceledException();
    }

    internal void Pulse()
    {
        lock (gate)
        {
            pulseRevision++;
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
    }

    internal async ValueTask WaitForControlCompletion(Task completion, CancellationToken cancellation)
    {
        while (!completion.IsCompleted)
        {
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            Task changedTask;
            lock (gate)
                changedTask = changed.Task;
            ProcessSignals?.Invoke();
            if (completion.IsCompleted)
                break;
            await Task.WhenAny(completion, changedTask).WaitAsync(cancellation);
        }
        cancellation.ThrowIfCancellationRequested();
        await completion;
    }

    public int Count
    {
        get
        {
            ProcessSignals?.Invoke();
            lock (gate)
                return admittedCount;
        }
    }

    internal Action<Term>? IncomingTerm { get; init; }

    public void Send(Term message, bool priority = false)
    {
        SendTraced(
            message,
            null,
            false,
            priority
        );
    }

    internal void SendTraced(
        Term message,
        SequenceTraceToken? token,
        bool preserve = false,
        bool priority = false,
        Term? from = null,
        bool traceAdmission = true,
        Term? distributionTraceToken = null
    )
    {
        IncomingTerm?.Invoke(message);
        if (from is not null)
            IncomingTerm?.Invoke(from);
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true)
                return;
            if (priority)
                lastPriority = lastPriority is null ? messages.AddFirst(new Entry(
                    message,
                    null,
                    false,
                    token,
                    preserve,
                    from,
                    traceAdmission,
                    distributionTraceToken
                )) : messages.AddAfter(lastPriority, new Entry(
                    message,
                    null,
                    false,
                    token,
                    preserve,
                    from,
                    traceAdmission,
                    distributionTraceToken
                ));
            else
                messages.AddLast(new Entry(
                    message,
                    null,
                    false,
                    token,
                    preserve,
                    from,
                    traceAdmission,
                    distributionTraceToken
                ));
            mutationRevision++;
            if (priority)
                precedenceRevision++;
            admittedCount++;
            QueueLengthChanged?.Invoke(admittedCount);
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
        if (traceAdmission)
            MessageAdmitted?.Invoke(message, from);
    }

    internal void SendPending(
        Term message,
        Func<bool?> admission,
        SequenceTraceToken? token = null,
        bool preserve = false,
        Term? from = null,
        bool traceAdmission = true,
        Term? distributionTraceToken = null
    )
    {
        IncomingTerm?.Invoke(message);
        if (from is not null)
            IncomingTerm?.Invoke(from);
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true)
                return;
            messages.AddLast(new Entry(
                message,
                admission,
                true,
                token,
                preserve,
                from,
                traceAdmission,
                distributionTraceToken
            ));
            pending++;
            mutationRevision++;
            precedenceRevision++;
            var previous = changed;
            changed = NewSignal();
            previous.TrySetResult();
        }
    }

    internal void AdmitPending()
    {
        var admitted = new List<(Term Message, Term? From)>();
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true || pending == 0)
                return;
            for (var node = messages.First; node is not null;)
            {
                var next = node.Next;
                if (node.Value.Deferred)
                    break;
                if (node.Value.Admission is { } admission)
                {
                    pending--;
                    mutationRevision++;
                    precedenceRevision++;
                    node.Value = node.Value with { Admission = null, Control = true };
                    bool? priority = admission();
                    if (priority is null)
                        RemoveNode(node);
                    else
                    {
                        node.Value = node.Value with { Control = false };
                        admittedCount++;
                        QueueLengthChanged?.Invoke(admittedCount);
                        if (node.Value.TraceAdmission)
                            admitted.Add((node.Value.Value, node.Value.From));
                        if (priority.Value)
                        {
                            messages.Remove(node);
                            if (lastPriority is null)
                                messages.AddFirst(node);
                            else
                                messages.AddAfter(lastPriority, node);
                            lastPriority = node;
                        }
                    }
                }
                node = next is not null && next.List == messages ? next : null;
            }
        }
        foreach (var admission in admitted)
            MessageAdmitted?.Invoke(admission.Message, admission.From);
    }

    internal void DiscardPending()
    {
        lock (gate)
        {
            if (HaltRequested?.Invoke() == true || pending == 0)
                return;
            for (var node = messages.First; node is not null;)
            {
                var next = node.Next;
                if (node.Value.Admission is not null || node.Value.Deferred)
                {
                    node.Value.DeferredRelease?.Invoke();
                    RemoveNode(node);
                }
                node = next;
            }
            pending = 0;
        }
    }

    public bool RemoveFirst(Func<Term, bool> predicate)
    {
        ProcessSignals?.Invoke();
        while (true)
        {
            LinkedListNode<Entry>? node;
            long revision;
            lock (gate)
            {
                node = messages.First;
                revision = precedenceRevision;
            }
            bool retry = false;
            while (node is not null)
            {
                Entry candidate;
                lock (gate)
                {
                    if (revision != precedenceRevision || !ReferenceEquals(node.List, messages))
                    {
                        retry = true;
                        break;
                    }
                    if (!IsAdmitted(node))
                    {
                        node = node.Next;
                        continue;
                    }
                    candidate = node.Value;
                }
                bool matched = predicate(candidate.Value);
                lock (gate)
                {
                    if (revision != precedenceRevision || !IsAdmitted(node))
                    {
                        retry = true;
                        break;
                    }
                    if (matched)
                    {
                        RemoveNode(node);

                        return true;
                    }
                    node = node.Next;
                }
            }
            if (!retry)
                return false;
            ProcessSignals?.Invoke();
        }
    }

    public int Remove(Func<Term, bool> predicate)
    {
        ProcessSignals?.Invoke();
        while (true)
        {
            (LinkedListNode<Entry> Node, Entry Value)[] candidates;
            long revision;
            lock (gate)
            {
                candidates = CaptureAdmitted();
                revision = mutationRevision;
            }
            var matched = new List<LinkedListNode<Entry>>();
            foreach (var candidate in candidates)
            {
                if (predicate(candidate.Value.Value))
                    matched.Add(candidate.Node);
            }
            lock (gate)
            {
                if (revision == mutationRevision && candidates.All(candidate => IsAdmitted(candidate.Node)))
                {
                    foreach (var node in matched)
                        RemoveNode(node);

                    return matched.Count;
                }
            }
            ProcessSignals?.Invoke();
        }
    }

    private (LinkedListNode<Entry> Node, Entry Value)[] CaptureAdmitted()
    {
        var captured = new List<(LinkedListNode<Entry>, Entry)>();
        for (var node = messages.First; node is not null; node = node.Next)
        {
            if (IsAdmitted(node))
                captured.Add((node, node.Value));
        }

        return captured.ToArray();
    }

    private bool IsAdmitted(LinkedListNode<Entry> node) =>
        ReferenceEquals(node.List, messages) && !node.Value.Control && node.Value.Admission is null;

    internal async Task WaitForMessage(CancellationToken cancellation)
    {
        try
        {
            await WaitForMessageCore(cancellation);
        }
        finally
        {
            WaitingStateChanged?.Invoke(false);
        }
    }

    private async Task WaitForMessageCore(CancellationToken cancellation)
    {
        while (true)
        {
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            ProcessSignals?.Invoke();
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            if (WaitForExecution is not null)
                await WaitForExecution();
            Task signal;
            bool retry;
            lock (gate)
            {
                retry = pending != 0;
                if (!retry && messages.Count != 0)
                    return;
                signal = changed.Task;
            }
            if (retry || ExecutionBlocked?.Invoke() == true)
                continue;
            WaitingStateChanged?.Invoke(true);
            await signal.WaitAsync(cancellation);
        }
    }

    public async ValueTask<T?> ReceiveAsync<T>(Func<Term, T?> select, TimeSpan? timeout, CancellationToken cancellation = default) where T : class
    {
        try
        {
            return await ReceiveCore(select, timeout, cancellation);
        }
        finally
        {
            WaitingStateChanged?.Invoke(false);
        }
    }

    private async ValueTask<T?> ReceiveCore<T>(Func<Term, T?> select, TimeSpan? timeout, CancellationToken cancellation) where T : class
    {
        if (timeout < TimeSpan.Zero)
            throw new ErlangException(ErlangErrorReasons.BadArgument);
        long start = Stopwatch.GetTimestamp();
        bool firstBatch = true;
        bool previousConflict = false;
        LinkedListNode<Entry>? resumeAfter = null;
        long resumeRevision = 0;
        while (true)
        {
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            ProcessSignals?.Invoke();
            ThrowIfHalted();
            cancellation.ThrowIfCancellationRequested();
            if (WaitForExecution is not null)
                start += await WaitForExecution();
            if (!firstBatch && timeout is { } finiteTimeout && finiteTimeout > TimeSpan.Zero && Stopwatch.GetElapsedTime(start) >= finiteTimeout)
            {
                ReceiveTimedOut?.Invoke();

                return null;
            }
            firstBatch = false;
            previousConflict = false;
            Task signal;
            bool retry;
            T? selected = null;
            Entry received = default;
            LinkedListNode<Entry>? node;
            long revision;
            long capturedPulse;
            LinkedListNode<Entry>? capturedTail;
            lock (gate)
            {
                retry = pending != 0;
                node = retry ? null : resumeAfter is not null && resumeRevision == precedenceRevision && IsAdmitted(resumeAfter)
                    ? resumeAfter.Next : messages.First;
                revision = precedenceRevision;
                capturedPulse = pulseRevision;
                capturedTail = messages.Last;
                signal = changed.Task;
            }
            resumeAfter = null;
            while (node is not null)
            {
                Entry candidate;
                lock (gate)
                {
                    if (revision != precedenceRevision || pending != 0 || !ReferenceEquals(node.List, messages))
                    {
                        retry = true;
                        break;
                    }
                    if (!IsAdmitted(node))
                    {
                        node = node.Next;
                        continue;
                    }
                    candidate = node.Value;
                }
                T? match = select(candidate.Value);
                ThrowIfHalted();
                cancellation.ThrowIfCancellationRequested();
                lock (gate)
                {
                    ThrowIfHalted();
                    cancellation.ThrowIfCancellationRequested();
                    if (revision != precedenceRevision || pending != 0 || !IsAdmitted(node)
                        || ExecutionBlocked?.Invoke() == true)
                    {
                        retry = true;
                        break;
                    }
                    if (match is not null)
                    {
                        selected = match;
                        received = candidate;
                        RemoveNode(node);
                        break;
                    }
                    if (ReferenceEquals(node, capturedTail))
                    {
                        resumeAfter = node;
                        resumeRevision = revision;
                        node = null;
                    }
                    else
                    {
                        node = node.Next;
                    }
                }
            }
            if (selected is null)
            {
                lock (gate)
                {
                    previousConflict = revision != precedenceRevision || capturedPulse != pulseRevision || pending != 0;
                    retry |= previousConflict || !ReferenceEquals(capturedTail, messages.Last) || !ReferenceEquals(signal, changed.Task);
                    if (previousConflict)
                        resumeAfter = null;
                    signal = changed.Task;
                }
            }
            if (selected is not null)
            {
                MessageReceived?.Invoke();
                SequenceTraceToken? traceToken = received.TraceToken;
                bool preserveTrace = received.PreserveTrace;
                if (received.DistributionTraceToken is { } rawTrace)
                {
                    var reception = DistributionSequenceTraceToken.Decode(rawTrace);
                    traceToken = reception.Token;
                    preserveTrace = reception.Preserve;
                }
                TraceReceived?.Invoke(received.Value, traceToken, preserveTrace);

                return selected;
            }
            if (timeout == TimeSpan.Zero && retry && !previousConflict && ExecutionBlocked?.Invoke() != true)
            {
                ReceiveTimedOut?.Invoke();

                return null;
            }
            if (retry || ExecutionBlocked?.Invoke() == true)
                continue;
            TimeSpan? remaining = timeout - Stopwatch.GetElapsedTime(start);
            if (remaining <= TimeSpan.Zero)
            {
                ReceiveTimedOut?.Invoke();

                return null;
            }
            try
            {
                if (remaining is { } finite)
                {
                    WaitingStateChanged?.Invoke(true);
                    await signal.WaitAsync(
                        finite > TimeSpan.FromMilliseconds(MailboxWaitParameters.MaximumSegmentMilliseconds) ? TimeSpan.FromMilliseconds(MailboxWaitParameters.MaximumSegmentMilliseconds) : finite,
                        cancellation
                    );
                }
                else
                {
                    WaitingStateChanged?.Invoke(true);
                    await signal.WaitAsync(cancellation);
                }
            }
            catch (TimeoutException)
            {
                continue;
            }
        }
    }

    private void RemoveNode(LinkedListNode<Entry> node)
    {
        bool ordinary = !node.Value.Control && node.Value.Admission is null;
        mutationRevision++;
        precedenceRevision++;
        if (ordinary)
            admittedCount--;
        if (ReferenceEquals(node, lastPriority))
            lastPriority = node.Previous;
        messages.Remove(node);
        if (ordinary)
            QueueLengthChanged?.Invoke(admittedCount);
    }

    internal IReadOnlyList<Term> Snapshot()
    {
        lock (gate)
            return messages.Where(entry => !entry.Control).Select(entry => entry.Value).ToArray();
    }
}

